/// Open `fixtures/model/<name>` (golden, checksums verified).
pub fn case(name: &str) -> Fixture {
    let dir = fixtures_root().join("model").join(name);
    let f = Fixture::open(&dir).unwrap_or_else(|e| panic!("{}: {e}", dir.display()));
    f.require_golden().unwrap();
    f.verify_checksums().unwrap();
    f
}

/// Every case id below `fixtures/model/<kind>`.
pub fn cases_of(kind: &str) -> Vec<String> {
    let dir = fixtures_root().join("model").join(kind);
    let mut out: Vec<String> = std::fs::read_dir(&dir)
        .map(|r| {
            r.filter_map(|e| e.ok())
                .filter(|e| e.path().join("manifest.json").exists())
                .map(|e| format!("{kind}/{}", e.file_name().to_string_lossy()))
                .collect()
        })
        .unwrap_or_default();
    out.sort();
    out
}

pub fn f64s(f: &Fixture, name: &str) -> Vec<f64> {
    f.load_f64(name)
        .unwrap_or_else(|e| panic!("{}: {name}: {e}", f.case_id()))
        .data
}

pub fn i64s(f: &Fixture, name: &str) -> Vec<i64> {
    f.load_i64(name)
        .unwrap_or_else(|e| panic!("{}: {name}: {e}", f.case_id()))
        .data
}

pub fn shape(f: &Fixture, name: &str) -> Vec<usize> {
    f.load_f64(name)
        .map(|x| x.shape)
        .or_else(|_| f.load_i64(name).map(|x| x.shape))
        .unwrap_or_else(|e| panic!("{}: {name}: {e}", f.case_id()))
}

pub fn has(f: &Fixture, name: &str) -> bool {
    f.quantity(name).is_ok()
}

pub fn bools(f: &Fixture, name: &str) -> Vec<bool> {
    let a = f.load(name).unwrap();
    let v = a
        .to_f64()
        .unwrap_or_else(|_| a.to_i64().unwrap().into_iter().map(|x| x as f64).collect());
    v.into_iter().map(|x| x != 0.0).collect()
}

pub fn param<'a>(f: &'a Fixture, key: &str) -> &'a serde_json::Value {
    &f.manifest().parameters[key]
}

/// Number of entries whose bits differ (exact comparison of decision D-046:
/// default NaNs of either sign match) and the largest relative difference.
pub fn diff_stats(a: &[f64], b: &[f64]) -> (usize, f64) {
    let scale = b.iter().fold(0.0f64, |m, v| m.nan_max(v.abs()));
    let mut n = a.len().abs_diff(b.len());
    let mut worst = 0.0f64;
    for (x, y) in a.iter().zip(b) {
        if !exact_eq(*y, *x) {
            n += 1;
            worst = worst.nan_max((x - y).abs() / scale.max(f64::MIN_POSITIVE));
        }
    }
    (n, worst)
}

/// Bit identity of `got` with `want` (`what` names the quantity; default
/// NaNs per D-046). Returns the number of **non-NaN** values compared bit
/// for bit: a NaN matched under D-046 is not counted as a bitwise value.
pub fn assert_bits_vec(case: &str, what: &str, got: &[f64], want: &[f64]) -> usize {
    let (n, worst) = diff_stats(got, want);
    assert!(
        n == 0,
        "{case}: {what}: {n} of {} values differ (max rel {worst:e})",
        want.len()
    );
    want.iter().filter(|v| !v.is_nan()).count()
}

/// Bit identity of `got` with the recorded quantity `name`.
pub fn assert_bits(f: &Fixture, name: &str, got: &[f64]) -> usize {
    let want = f64s(f, name);
    assert_bits_vec(f.case_id(), name, got, &want)
}

/// Read a Gmsh mesh.
pub fn read_mesh(path: &Path, dim: usize) -> Mesh {
    let mut mesh = Mesh::new(dim, "mesh").unwrap();
    akantu_io::read_mesh(&mut mesh, path, MeshIoType::Gmsh).unwrap();
    mesh
}

/// Model on the fixture's mesh and material file, every upstream-defect
/// switch in its default (corrected) mode: no case replayed through this
/// helper needs a compat switch (the elastic laws of
/// these fixtures do not reach the UD-038/109/033/104/105 paths).
pub fn model_of(f: &Fixture) -> SolidMechanicsModel {
    let dim = param(f, "spatial_dimension").as_u64().unwrap() as usize;
    let mesh = read_mesh(&f.input_path("mesh").unwrap(), dim);
    let parser = Parser::parse_file(f.input_path("material").unwrap()).unwrap();
    SolidMechanicsModel::with_parser(SharedMesh::new(mesh), None, "solid_mechanics_model", parser)
        .unwrap()
}

/// Model on `mesh` with the material text `dat` (default mode of every
/// upstream-defect switch).
pub fn model_with(mesh: Mesh, dat: &str) -> SolidMechanicsModel {
    let parser = Parser::parse_str(dat, "material.dat").unwrap();
    SolidMechanicsModel::with_parser(SharedMesh::new(mesh), None, "solid_mechanics_model", parser)
        .unwrap()
}

/// Set the Newton–Raphson parameters of the default solver.
pub fn set_newton(
    model: &mut SolidMechanicsModel,
    max_iterations: i64,
    threshold: f64,
    criterion: &str,
) {
    let nls = model.solver.non_linear_solver_mut(None).unwrap();
    nls.set_param("max_iterations", ParamValue::Int(max_iterations))
        .unwrap();
    nls.set_param("threshold", ParamValue::Real(threshold))
        .unwrap();
    nls.set_param("convergence_type", ParamValue::Enum(criterion.into()))
        .unwrap();
}

/// `[tuple, dim, dim]` column-major tuples → `[tuple, row, col]` row-major
/// (fixture layout).
pub fn col_major_to_rows(values: &[Real], dim: usize) -> Vec<Real> {
    let mut out = Vec::with_capacity(values.len());
    for t in values.chunks_exact(dim * dim) {
        for r in 0..dim {
            for c in 0..dim {
                out.push(t[r + c * dim]);
            }
        }
    }
    out
}

/// Element types of dimension `dim` (not ghost, regular kind).
pub fn types_of(mesh: &Mesh, dim: usize) -> Vec<ElementType> {
    mesh.element_types(TypeFilter {
        spatial_dimension: Some(dim),
        ghost_type: GhostType::NotGhost,
        kind: Some(akantu_core::ElementKind::Regular),
    })
    .collect()
}

/// Upstream element type name (`_triangle_3`).
pub fn tname(ty: ElementType) -> String {
    ty.to_string()
}

/// Material 0 internal `name` of type `ty` as `[element, quad, row, col]`
/// in the element order of the mesh (single-material models: filter order
/// = mesh order).
pub fn law_tensor(model: &SolidMechanicsModel, name: &str, ty: ElementType) -> Vec<Real> {
    let d = model.spatial_dimension();
    let law = model.material(0).unwrap();
    let field = match name {
        "stress" => &law.base().stress,
        "grad_u" => &law.base().grad_u,
        _ => panic!("internal {name}"),
    };
    col_major_to_rows(field.get(ty, GhostType::NotGhost).unwrap().as_slice(), d)
}

/// Default solver initialisation of a model.
pub fn init(model: &mut SolidMechanicsModel, method: AnalysisMethod) {
    model.init_full(&ModelOptions::new(method)).unwrap();
}

/// Boundary facets of the elements of dimension `dim` (faces belonging to
/// exactly one element; sorted node keys), added to the mesh as
/// `(dim − 1)` elements in first-encounter order and grouped in the element
/// group `boundary_0` (stand-in for upstream `MeshUtils::buildFacets` +
/// `createBoundaryGroupFromGeometry` on a connected domain, not on
/// this base).
pub fn add_boundary_group(mesh: &mut Mesh, dim: usize) -> String {
    use std::collections::HashMap;
    let types = types_of(mesh, dim);
    let mut faces: HashMap<Vec<Idx>, (ElementType, Vec<Idx>, usize)> = HashMap::new();
    let mut order = Vec::new();
    for ty in &types {
        let fc = ty.facet_connectivity(0).unwrap();
        let fty = ty.facet_type(0).unwrap();
        let conn = mesh.connectivity(*ty, GhostType::NotGhost).unwrap();
        for e in 0..conn.len() {
            let t = conn.tuple(e);
            for f in 0..fc.nb_facets {
                let nodes: Vec<Idx> = fc.facet(f).map(|n| t[n]).collect();
                let mut key = nodes.clone();
                key.sort_unstable();
                let entry = faces.entry(key.clone()).or_insert_with(|| {
                    order.push(key.clone());
                    (fty, nodes.clone(), 0)
                });
                entry.2 += 1;
            }
        }
    }
    let boundary: Vec<(ElementType, Vec<Idx>)> = order
        .into_iter()
        .filter_map(|k| {
            let (t, n, c) = &faces[&k];
            (*c == 1).then(|| (*t, n.clone()))
        })
        .collect();
    let mut added: Vec<(ElementType, Idx)> = Vec::new();
    {
        let mut acc = MeshAccessor::new(mesh);
        for (t, n) in &boundary {
            let mut c = acc.connectivity_mut(*t, GhostType::NotGhost);
            let i = c.len() as Idx;
            c.push_tuple(n);
            added.push((*t, i));
        }
    }
    let name = "boundary_0".to_owned();
    let groups = mesh.groups_mut();
    let mut g = groups.create_element_group(&name, dim - 1).unwrap();
    for (t, i) in &added {
        g.add(Element::new(*t, *i, GhostType::NotGhost), None, false)
            .unwrap();
    }
    let mut nodes: Vec<Idx> = boundary.iter().flat_map(|(_, n)| n.clone()).collect();
    nodes.sort_unstable();
    nodes.dedup();
    for n in nodes {
        g.add_node(n, false);
    }
    name
}

/// Path of a copied upstream test data file
/// (`crates/akantu-solid/tests/data/<rel>`).
pub fn data(rel: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/data")
        .join(rel)
}

/// Copy of the fixture-free `Array` values.
pub fn values(a: &Array<Real>) -> Vec<Real> {
    a.as_slice().to_vec()
}
